/// <summary>
/// MPJ_3338_AMEXCustomerPaymentProcessing
/// UI Builder class for customer payment proposal batch job
/// </summary>
class METAMEXCustPaymProposalUIBuilder extends SysOperationAutomaticUIBuilder
{
    DialogField                     ledgerNameDlgField;
    DialogField                     companiesDlgField;
    DialogField                     paymentRunDlgField;

    DialogEnumComboBox              dialogEnumComboBox;    
    SysLookupMultiSelectCtrl        companyMultiSelectCtrl;

    CustAccountStatement            accountStatement;
    
}

Method.Source:
    public void postBuild()
    {
        super();

        ledgerNameDlgField  = this.bindInfo().getDialogField(this.dataContractObject(),
        methodStr(METAMEXCustPaymProposalContract, parmJournalName));

        companiesDlgField     =  this.bindInfo().getDialogField(this.dataContractObject(),
                                    methodStr(METAMEXCustPaymProposalContract, parmSelectedCompanies));
        companiesDlgField.lookupButton(FormLookupButton::Always);

        paymentRunDlgField   = this.bindInfo().getDialogField(this.dataContractObject(),
                                    methodStr(METAMEXCustPaymProposalContract, parmPaymentRun));

        Set enumSet = new Set(Types::Enum);
        enumSet.add(CustAccountStatement::AMEXNone);
        enumSet.add(CustAccountStatement::AMEXWeekly);
        enumSet.add(CustAccountStatement::AMEXFortnightly);
        enumSet.add(CustAccountStatement::AMEXMonthly);
        enumSet.add(CustAccountStatement::AMEXPeriod);
        enumSet.add(CustAccountStatement::Yearly);

        dialogEnumComboBox = DialogEnumComboBox::newParameters(null, paymentRunDlgField.control().ID(), enumNum(CustAccountStatement), enumSet, this.dialog().form());
    }

    public void postRun()
    {
        super();

        ledgerNameDlgField.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METAMEXCustPaymProposalUIBuilder, ledgerNameLookUp), this);
        
        this.companyLookUp();

        dialogEnumComboBox.parmFormRun(this.dialog().dialogForm().formRun());

    }

    /// <summary>
    /// MPJ_3888_AMEXCustomerPaymentProcessing
    /// Customer payment LedgerName lookup
    /// </summary>
    /// <param name = "_control">object of data</param>
    public void ledgerNameLookUp(FormStringControl  _control)
    {
        Query						query = new Query();
        QueryBuildDataSource        qbd;
        SysTableLookup			    sysTableLookup;

        sysTablelookup = SysTableLookup::newParameters(tableNum(LedgerJournalName), _control);
        sysTablelookup.addLookupfield(fieldNum(LedgerJournalName,JournalName));
        sysTablelookup.addLookupfield(fieldNum(LedgerJournalName,Name));

        qbd = query.addDataSource(tableNum(LedgerJournalName));
        qbd.addSortField(fieldnum(LedgerJournalName, JournalName));

        qbd.addRange(fieldNum(LedgerJournalName,JournalType)).value(enum2Str(LedgerJournalType::CustPayment));

        sysTableLookup.parmQuery(query);
        sysTablelookup.performFormLookup();

    }

    /// <summary>
    /// MPJ_3888_AMEXCustomerPaymentProcessing
    /// Customer payment company lookup
    /// </summary>
    public void companyLookUp()
    {
        Query		            query           = new Query();
        QueryBuildDataSource    qbdsLegalEntity = query.addDataSource(tablenum(CompanyInfo));
 
        qbdsLegalEntity.fields().addField(fieldNum(CompanyInfo, DataArea));
        qbdsLegalEntity.fields().addField(fieldNum(CompanyInfo, Name));
 
        qbdsLegalEntity.addSortField(fieldNum(CompanyInfo, DataArea), SortOrder::Ascending);
        container selectedFields = [tableNum(CompanyInfo), fieldNum(CompanyInfo, DataArea)];
 
        companyMultiSelectCtrl = SysLookupMultiSelectCtrl::constructWithQuery(this.dialog().dialogForm().formRun(), companiesDlgField.control(), query, true, selectedFields);

    }

    /// <summary>
    ///    Transfers data from the dialog into the data contract object.
    /// </summary>
    public void getFromDialog()
    {
        METAMEXCustPaymProposalContract   dataContract;
        super();

        dataContract    =  this.dataContractInfo().dataContractObject();
        accountStatement = dialogEnumComboBox.selection();
        dataContract.parmPaymentRun(accountStatement);
    }
